using System.Windows;namespace UserRegistrationWPF.Views{public partial class MainWindow:Window{public MainWindow(){InitializeComponent();}private void btnRegister_Click(object sender,RoutedEventArgs e){var vm=new RegistrationData{FullName=txtFullName.Text,Email=txtEmail.Text,Phone=txtPhone.Text,Username=txtUsername.Text,Password=txtPassword.Text};var display=new DisplayWindow(vm){Owner=this};display.ShowDialog();}}public class RegistrationData{public string FullName{get;set;}=string.Empty;public string Email{get;set;}=string.Empty;public string Phone{get;set;}=string.Empty;public string Username{get;set;}=string.Empty;public string Password{get;set;}=string.Empty;}}